-/// Montgomery reduction of an 8-limb value before the final conditional
-/// subtraction, with the products by the modulus limbs written as shifts.
+#[inline(always)]
+#[allow(clippy::too_many_arguments)]
+fn montgomery_reduce_words_wide(
+    r0: u64,
+    r1: u64,
+    r2: u64,
+    r3: u64,
+    r4: u64,
+    r5: u64,
+    r6: u64,
+    r7: u64,
+) -> [u64; 5] {
+    let (r1, carry) = mac(r1, r0, MODULUS[1], r0);
+    let (r2, carry) = adc(r2, 0, carry);
+    let (r3, carry) = mac(r3, r0, MODULUS[3], carry);
+    let (r4, carry2) = adc(r4, 0, carry);
+
+    let (r2, carry) = mac(r2, r1, MODULUS[1], r1);
+    let (r3, carry) = adc(r3, 0, carry);
+    let (r4, carry) = mac(r4, r1, MODULUS[3], carry);
+    let (r5, carry2) = adc(r5, carry2, carry);
+
+    let (r3, carry) = mac(r3, r2, MODULUS[1], r2);
+    let (r4, carry) = adc(r4, 0, carry);
+    let (r5, carry) = mac(r5, r2, MODULUS[3], carry);
+    let (r6, carry2) = adc(r6, carry2, carry);
+
+    let (r4, carry) = mac(r4, r3, MODULUS[1], r3);
+    let (r5, carry) = adc(r5, 0, carry);
+    let (r6, carry) = mac(r6, r3, MODULUS[3], carry);
+    let (r7, r8) = adc(r7, carry2, carry);
+
+    [r4, r5, r6, r7, r8]
+}
+
+/// Same result as [`montgomery_reduce_words_wide`], with the products by
+/// the modulus limbs written as shifts.

